def migrate_legacy_comments(apps, schema_editor):
    """把订单商品上的旧评论迁入独立评论表，旧评论视为已通过。"""
    OrderGoods = apps.get_model("order", "OrderGoods")
    OrderComment = apps.get_model("order", "OrderComment")
    for line in (
        OrderGoods.objects.exclude(comment__isnull=True)
        .exclude(comment="")
        .iterator()
    ):
        content = (line.comment or "").strip()
        if not content:
            continue
        OrderComment.objects.create(
            order_goods_id=line.pk,
            content=content[:500],
            status=1,
        )


